import tarfile,pathlib,io
def extract(archive,destination,max_bytes):
    dest=pathlib.Path(destination)
    if dest.exists() or type(max_bytes) is not int or max_bytes<0:raise ValueError('invalid destination/budget')
    entries={};payload={};total=0
    with tarfile.open(archive,'r:*') as package:
        for m in package.getmembers():
            p=pathlib.PurePosixPath(m.name)
            if not p.parts or p.is_absolute() or '..' in p.parts or str(p)!=m.name.rstrip('/') or (m.isfile() and m.name.endswith('/')) or not (m.isdir() or m.isfile()) or str(p) in entries:raise ValueError('unsafe member')
            name=str(p);entries[name]='dir' if m.isdir() else 'file'
            if m.isfile():
                total+=m.size
                if total>max_bytes:raise ValueError('budget exceeded')
                data=package.extractfile(m).read()
                if len(data)!=m.size:raise ValueError('truncated data')
                payload[name]=data
    for name in entries:
        parts=pathlib.PurePosixPath(name).parts
        for i in range(1,len(parts)):
            if entries.get('/'.join(parts[:i]))=='file':raise ValueError('file/directory collision')
    dest.mkdir()
    for name,kind in sorted(entries.items()):
        p=dest/name
        if kind=='dir':p.mkdir(parents=True,exist_ok=True)
        else:
            p.parent.mkdir(parents=True,exist_ok=True)
            with p.open('xb') as stream:stream.write(payload[name])
    return sorted(payload)
```

