import os,tempfile,pathlib
def alter(path,mode):
    path=pathlib.Path(path);fd=os.open(path,os.O_RDONLY)
    try:
        if mode=='unlink':path.unlink()
        elif mode=='truncate':
            with path.open('r+b') as stream:stream.truncate(0)
        elif mode=='replace':
            n,t=tempfile.mkstemp(dir=path.parent)
            try:
                with os.fdopen(n,'wb') as stream:stream.write(b'replacement')
                os.replace(t,path)
            finally:
                if os.path.exists(t):os.unlink(t)
        else:raise ValueError('mode')
        return dict(old_fd_bytes=os.read(fd,100000),path_bytes=path.read_bytes() if path.exists() else None,same_inode=os.fstat(fd).st_ino==path.stat().st_ino if path.exists() else None,old_nlink=os.fstat(fd).st_nlink)
    finally:os.close(fd)
