import os,stat,base64
def inventory(root):
    root=os.fsencode(root);rows=[]
    def visit(directory,prefix):
        for name in os.listdir(directory):
            path=os.path.join(directory,name);relative=os.path.join(prefix,name);info=os.lstat(path)
            if stat.S_ISLNK(info.st_mode):rows.append((relative,dict(path_b64=base64.b64encode(relative).decode(),kind='symlink',size=info.st_size)))
            elif stat.S_ISREG(info.st_mode):rows.append((relative,dict(path_b64=base64.b64encode(relative).decode(),kind='file',size=info.st_size)))
            elif stat.S_ISDIR(info.st_mode):visit(path,relative)
    visit(root,b'')
    return [row for _,row in sorted(rows)]
